test("未知の型のノードが子を並べない親の下で fill を持つと、未知の型のエラーのあとに fill のエラーが続く", () => {
  const errors = errorsOf({}, [
    {
      name: "panel",
      type: "Box",
      props: { layout: "free" },
      children: [
        { name: "widget", type: "Button", props: { widthMode: "fill" } },
      ],
    },
  ]);

  expect(errors).toStrictEqual([
    {
      kind: "unknown-type",
      nodeName: "widget",
      message: 'unknown type "Button"',
    },
    {
      kind: "fill-in-free-parent",
      nodeName: "widget",
      prop: "widthMode",
      message:
        'prop "widthMode" cannot be "fill" inside a parent that does not arrange its children',
    },
  ]);
});

test("未知の型のノードのエラーは、そのノード名の位置で prop を持たず、型名を挙げる", () => {
  const errors = errorsOf({}, [{ name: "widget", type: "Button" }]);

  expect(errors).toStrictEqual([
    {
      kind: "unknown-type",
      nodeName: "widget",
      message: 'unknown type "Button"',
    },
  ]);
});

test("循環参照に含まれる部品のエラーは、部品ごとにその部品名の位置で prop を持たない", () => {
  const errors = errorsOf(
    {
      a: { type: "Box", children: [{ name: "a-inner", ref: "b" }] },
      b: { type: "Box", children: [{ name: "b-inner", ref: "a" }] },
    },
    [],
  );

  expect(errors).toStrictEqual([
    {
      kind: "circular-ref",
      nodeName: "a",
      message: 'component "a" is part of a circular reference',
    },
    {
      kind: "circular-ref",
      nodeName: "b",
      message: 'component "b" is part of a circular reference',
    },
  ]);
});

test("エラーは artboard のエラー・部品の循環参照・名前のエラー・色トークンのエラーの順に並ぶ", () => {
  const document = DesignDocument.create({
    tokens: { ...TokenSet.empty(), colors: { bad: "red" } },
    components: {
      a: { type: "Box", children: [{ name: "a-inner", ref: "b" }] },
      b: { type: "Box", children: [{ name: "b-inner", ref: "a" }] },
    },
    artboards: [
      {
        name: "screen",
        width: 375,
        height: 812,
        props: { notAProp: true },
        children: [
          { name: "label", type: "Box" },
          { name: "label", type: "Box" },
        ],
      },
    ],
  });

  const errors = DesignDocument.collectErrors(document);

  expect(errors).toEqual([
    expect.objectContaining({ kind: "unknown-prop", nodeName: "screen" }),
    expect.objectContaining({ kind: "circular-ref", nodeName: "a" }),
    expect.objectContaining({ kind: "circular-ref", nodeName: "b" }),
    expect.objectContaining({ kind: "duplicate-name", nodeName: "label" }),
    expect.objectContaining({ kind: "invalid-color", tokenName: "bad" }),
  ]);
});

test("artboard の props のエラーは、その artboard の子のエラーより前に並ぶ", () => {
  const document = DesignDocument.create({
    artboards: [
      {
        name: "screen",
        width: 375,
        height: 812,
        props: { notAProp: true },
        children: [{ name: "plain", type: "Box", props: { "plain-extra": 1 } }],
      },
    ],
  });

  const errors = DesignDocument.collectErrors(document);

  expect(errors).toEqual([
    expect.objectContaining({
      kind: "unknown-prop",
      nodeName: "screen",
      prop: "notAProp",
    }),
    expect.objectContaining({
      kind: "unknown-prop",
      nodeName: "plain",
      prop: "plain-extra",
    }),
  ]);
});

test("名前のエラーはノード名の規則違反・名前の重複・トークン名の規則違反・colors と gradients の名前の衝突の順に並ぶ", () => {
  const document = DesignDocument.create({
    tokens: {
      ...TokenSet.empty(),
      colors: { brand: "#3b82f6" },
      gradients: { brand: Fade },
      spacing: { Big: 8 },
    },
    artboards: [
      {
        name: "screen",
        width: 375,
        height: 812,
        children: [
          { name: "LoginForm", type: "Box" },
          { name: "label", type: "Box" },
          { name: "label", type: "Box" },
        ],
      },
    ],
  });

  const errors = DesignDocument.collectErrors(document);

  expect(errors).toEqual([
    expect.objectContaining({
      kind: "invalid-identifier",
      nodeName: "LoginForm",
    }),
    expect.objectContaining({ kind: "duplicate-name", nodeName: "label" }),
    expect.objectContaining({ kind: "invalid-identifier", tokenName: "Big" }),
    expect.objectContaining({
      kind: "conflicting-token-name",
      tokenName: "brand",
    }),
  ]);
});
